UNITS = {'s': 1, 'm': 60, 'h': 3600}


def parse_duration(s):
    s = s.strip()
    unit = s[-1]
    if unit not in UNITS:
        raise ValueError(f'unknown unit in {s!r}')
    return float(s[:-1]) * UNITS[unit]

